import {openHistory} from './history-store.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const productKey=(brand,product)=>JSON.stringify([brand,product]);
let profiles=[];
export async function loadProducts(){const db=await openHistory();profiles=await new Promise((resolve,reject)=>{const r=db.transaction('settings').objectStore('settings').get('productProfiles');r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(Error('读取产品档案失败'))});return profiles}
export const exportProducts=()=>profiles;
export function validateProducts(value=[]){if(!Array.isArray(value)||value.length>2000)throw Error('产品档案格式不正确');return value.map(p=>{if(!p||typeof p.brand!=='string'||!p.brand.trim()||p.brand.length>100||typeof p.product!=='string'||!p.product.trim()||p.product.length>1000||typeof p.image!=='string'||p.image.length>600000||!(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.image)||p.image===''))throw Error('产品图片或名称格式不正确');return {brand:p.brand,product:p.product,image:p.image,notes:String(p.notes||'').slice(0,1000)}})}
async function writeProducts(next){const db=await openHistory();await new Promise((resolve,reject)=>{const tx=db.transaction('settings','readwrite');tx.objectStore('settings').put(next,'productProfiles');tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(Error('产品档案保存失败，请检查浏览器存储空间'))});profiles=next}
export async function importProducts(value){const next=[...profiles],keys=new Set(next.map(p=>productKey(p.brand,p.product)));for(const p of value){const key=productKey(p.brand,p.product);if(!keys.has(key)){next.push(p);keys.add(key)}}await writeProducts(next)}
export function groupProducts(records,filters={}){const groups=new Map(profiles.map(p=>[productKey(p.brand,p.product),{...p,total:0,batches:0,platforms:new Set(),latest:''}]));for(const r of records){const products=new Set(r.comments.map(c=>c.product));for(const product of products){const key=productKey(r.brand,product);if(!groups.has(key))groups.set(key,{brand:r.brand,product,image:'',notes:'',total:0,batches:0,platforms:new Set(),latest:''});const g=groups.get(key),comments=r.comments.filter(c=>c.product===product);g.total+=comments.length;g.batches++;comments.forEach(c=>g.platforms.add(c.platform));if(r.collectedAt>g.latest)g.latest=r.collectedAt}}
return [...groups.values()].filter(g=>(!filters.brand||filters.brand==='全部'||g.brand===filters.brand)&&(!filters.product||filters.product==='全部'||g.product===filters.product)&&(!filters.platform||filters.platform==='全部'||g.platforms.has(filters.platform)))}
export function productGallery(records,filters){const groups=groupProducts(records,filters);return `<section class="product-section"><div class="card-head"><div><div class="eyebrow">一款产品，一份持续积累的档案</div><h2>产品档案</h2></div><button id="product-new">＋ 新建产品档案</button></div><p class="muted">按品牌与产品名称自动归集；填写一致的名称，新评论就会进入同一档案。产品图由你上传。</p><div class="product-grid">${groups.map((g,i)=>`<article class="card product-card"><div class="product-cover">${g.image?`<img src="${g.image}" alt="${esc(g.brand+' '+g.product)}产品图">`:'<div class="product-placeholder"><span>▧</span><small>添加产品实拍或官方图片</small></div>'}<button data-product-edit="${i}" aria-label="编辑${esc(g.product)}图片与资料">${g.image?'更换图片 / 编辑':'＋ 添加产品图片'}</button></div><div class="product-info"><div class="eyebrow">${esc(g.brand)}</div><h3>${esc(g.product)}</h3>${g.notes?`<p class="product-notes">${esc(g.notes)}</p>`:''}<div class="product-counts"><span><b>${g.total}</b> 条评论</span><span><b>${g.batches}</b> 次分析</span></div><div class="history-tags">${[...g.platforms].map(p=>`<span>${esc(p)}</span>`).join('')||'<span>等待导入评论</span>'}</div><small>最近采集：${g.latest||'尚无记录'}</small><button data-product-open="${i}" ${g.batches?'':'disabled'}>查看记录与对比 →</button></div></article>`).join('')}</div>${groups.length?'':'<div class="empty">新建产品档案、上传封面，或导入评论自动生成档案。</div>'}</section><dialog id="product-editor" class="product-editor"><form id="product-form"><div class="card-head"><h2>产品图片与资料</h2><button type="button" id="product-close" aria-label="关闭产品编辑">×</button></div><label>品牌名称<input id="product-brand" maxlength="100" required placeholder="例如：伊菲丹"></label><label>产品名称<input id="product-name" maxlength="1000" required placeholder="例如：超级面膜"></label><label>产品图片<input id="product-image" type="file" accept="image/jpeg,image/png,image/webp"></label><small>支持 JPG / PNG / WebP，单张不超过 10 MB。图片会压缩后保存在当前浏览器。</small><div id="product-image-preview"></div><label>产品备注（选填）<textarea id="product-notes" maxlength="1000" rows="3" placeholder="记录规格、系列或你的研究备注"></textarea></label><p id="product-error" role="alert"></p><button type="submit" class="primary" id="product-save">保存产品档案</button></form></dialog>`}
async function imageData(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('请选择 10 MB 以内的 JPG、PNG 或 WebP 图片');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#FAF7F2';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.82);if(data.length>600000)data=canvas.toDataURL('image/jpeg',.55);if(data.length>600000)throw Error('图片压缩后仍过大，请使用更小的图片');return data}finally{bitmap.close()}}
export function bindProducts(records,filters,onSelect,onRender){const $=s=>document.querySelector(s),dialog=$('#product-editor');if(!dialog)return;const groups=groupProducts(records,filters);let draftImage='',processing=false;const preview=()=>{$('#product-image-preview').innerHTML=draftImage?`<img src="${draftImage}" alt="待保存产品图">`:''};function edit(g){$('#product-form').reset();$('#product-brand').value=g?.brand||'';$('#product-name').value=g?.product||'';$('#product-brand').readOnly=!!g;$('#product-name').readOnly=!!g;$('#product-notes').value=g?.notes||'';draftImage=g?.image||'';$('#product-error').textContent='';preview();dialog.showModal()}$('#product-new').onclick=()=>edit();$('#product-close').onclick=()=>{if(!processing)dialog.close()};document.querySelectorAll('[data-product-edit]').forEach(b=>b.onclick=()=>edit(groups[Number(b.dataset.productEdit)]));document.querySelectorAll('[data-product-open]').forEach(b=>b.onclick=()=>onSelect(groups[Number(b.dataset.productOpen)]));$('#product-image').onchange=async e=>{const f=e.target.files[0];if(!f)return;processing=true;$('#product-save').disabled=true;$('#product-error').textContent='正在处理图片…';try{draftImage=await imageData(f);preview();$('#product-error').textContent=''}catch(err){$('#product-error').textContent=err.message}finally{processing=false;$('#product-save').disabled=false}};$('#product-form').onsubmit=async e=>{e.preventDefault();if(processing)return;const brand=$('#product-brand').value.trim(),product=$('#product-name').value.trim();if(!brand||!product){$('#product-error').textContent='请填写品牌和产品名称';return}const next={brand,product,image:draftImage,notes:$('#product-notes').value.trim()},key=productKey(brand,product);if(!$('#product-brand').readOnly&&profiles.some(p=>productKey(p.brand,p.product)===key)){$('#product-error').textContent='该产品档案已存在，请在卡片上编辑';return}processing=true;$('#product-save').disabled=true;try{validateProducts([next]);await writeProducts([...profiles.filter(p=>productKey(p.brand,p.product)!==key),next]);dialog.close();onRender()}catch(err){$('#product-error').textContent=err.message}finally{processing=false;$('#product-save').disabled=false}}}
